1	import { useEffect, useRef, useState } from "react";
2	import { fetchFollowedArtists } from "./spotify.js";
3	
4	// The server answers a denied caller with the lock's exact remaining TTL
5	// (server/kv.js getThrottleRetryMs). That is ideal for a single caller and
6	// pathological for several: every worker denied during the same hold wakes at
7	// the same instant to contend for a lock only one can win, and the losers are
8	// denied again. A small random spread staggers the wake-ups.
9	const RETRY_JITTER_MS = 250;
10	
11	// Workers pulling from one shared queue. Sized to keep the server-side
12	// MusicBrainz lock busy without piling up requests that can only be denied:
13	// a lookup holds that lock for 1-2 intervals, so a couple of workers
14	// saturate it and anything beyond that just burns serverless invocations on
15	// throttled responses.
16	//
17	// 2 is measured, not guessed. A 242-artist cold run at 4 never once had 4
18	// lookups in flight (peak 3, mean 1.37 while busy) and cost 3.4 throttle
19	// denials per lookup against 0.8 for the old sequential loop — the extra
20	// workers only bought denied requests. The floor is ~1500ms/artist: a
21	// typical lookup's work takes ~500ms but holds the lock for at least
22	// GEOCODE_MIN_INTERVAL_MS, so the quiet after it is the 1 req/s budget
23	// being honored, not slack that more concurrency can fill.
24	const DEFAULT_RESOLUTION_CONCURRENCY = 2;
25	
26	// Vite substitutes import.meta.env.VITE_* at BUILD time — this is a baked-in
27	// constant, not a runtime lookup, so retuning it needs a redeploy rather than
28	// just an env change. Anything unset or nonsensical falls back to the
29	// measured default rather than failing the whole resolution loop.
30	export function parseConcurrency(
31	  raw,
32	  fallback = DEFAULT_RESOLUTION_CONCURRENCY,
33	) {
34	  const n = Number.parseInt(raw, 10);
35	  return Number.isInteger(n) && n > 0 ? n : fallback;
36	}
37	
38	const RESOLUTION_CONCURRENCY = parseConcurrency(
39	  import.meta.env?.VITE_RESOLUTION_CONCURRENCY,
40	);
41	
42	// Cancellable delay: rejects immediately (or as soon as `signal` aborts)
43	// instead of resolving, so a stale throttled-retry timer never fires a
44	// request for a loop whose effect has already been cleaned up.
45	function delay(ms, signal) {
46	  return new Promise((resolve, reject) => {
47	    if (signal.aborted) {
48	      reject(new DOMException("Aborted", "AbortError"));
49	      return;
50	    }
51	    const id = setTimeout(resolve, ms);
52	    signal.addEventListener(
53	      "abort",
54	      () => {
55	        clearTimeout(id);
56	        reject(new DOMException("Aborted", "AbortError"));
57	      },
58	      { once: true },
59	    );
60	  });
61	}
62	
63	// Resolution loop: RESOLUTION_CONCURRENCY workers pulling artists off one
64	// shared queue. Runs at app boot (keyed on token) regardless of whether
65	// explore mode is visible, so the map has clustered markers ready by the
66	// time the user opens it.
67	export function useLibraryArtists(token) {
68	  const [artists, setArtists] = useState([]);
69	  const [resolvedCount, setResolvedCount] = useState(0);
70	  const [total, setTotal] = useState(0);
71	  const [scopeMissing, setScopeMissing] = useState(false);
72	  // Artists whose /api/geocode call failed for backend/network reasons
73	  // (see resolveArtist below) — tracked separately from resolvedCount so a
74	  // failure is never indistinguishable from a legitimate not_found.
75	  const [failedCount, setFailedCount] = useState(0);
76	  const mountedRef = useRef(true);
77	
78	  useEffect(() => {
79	    mountedRef.current = true;
80	    return () => {
81	      mountedRef.current = false;
82	    };
83	  }, []);
84	
85	  useEffect(() => {
86	    if (!token) return;
87	
88	    let cancelled = false;
89	    // One controller per effect run (i.e. per token), shared by every worker.
90	    // Its cleanup aborts every /api/geocode request in flight and cancels any
91	    // pending throttled-retry timer, so a token change (e.g. the routine
92	    // TOKEN_EXPIRED refresh in MapView.jsx) can never leave a stale request
93	    // racing the new loop's — nothing from the old token survives it.
94	    const controller = new AbortController();
95	    const isLive = () => !cancelled && mountedRef.current;
96	
97	    function updateArtist(id, patch) {
98	      setArtists((prev) =>
99	        prev.map((a) => (a.id === id ? { ...a, ...patch } : a)),
100	      );
101	    }
102	
103	    // Resolves one artist, retrying in place on "throttled" until it gets a
104	    // terminal result. Never advances resolvedCount for a throttled retry.
105	    async function resolveArtist(artist) {
106	      for (;;) {
107	        if (!isLive()) return;
108	
109	        let result;
110	        try {
111	          const response = await fetch("/api/geocode", {
112	            method: "POST",
113	            headers: { "Content-Type": "application/json" },
114	            body: JSON.stringify({
115	              artistId: artist.id,
116	              artistName: artist.name,
117	            }),
118	            signal: controller.signal,
119	          });
120	          // Non-200 (e.g. a raw 500 — api/geocode.js wraps its own Redis
121	          // calls and declares this as {status: "unavailable"}, but a
122	          // network hop between us and Vercel can still surface as some
123	          // other non-200, or 401/400/405) is treated as a resolution
124	          // failure for this artist rather than retried: retrying an outage
125	          // would spin the loop hot, and this artist isn't special. It is
126	          // NOT treated as "not_found" though — that's a legitimate
127	          // negative result from MusicBrainz/Nominatim, and this isn't one
128	          // (see the "unavailable" handling below). Only "throttled" (a 200
129	          // response) retries, since that's the server explicitly asking us
130	          // to wait, with a bounded backoff it names itself.
131	          result = response.ok
132	            ? await response.json()
133	            : { status: "unavailable" };
134	        } catch {
135	          // Covers both a genuine network failure (treated like a non-200
136	          // above) and this request being aborted by cleanup on a token
137	          // change — the isLive() check right below discards `result` in
138	          // the abort case, so it never gets marked unavailable or counted.
139	          result = { status: "unavailable" };
140	        }
141	
142	        if (!isLive()) return;
143	
144	        if (result.status === "throttled") {
145	          try {
146	            await delay(
147	              result.retryAfterMs + Math.random() * RETRY_JITTER_MS,
148	              controller.signal,
149	            );
150	          } catch {
151	            return; // aborted while waiting to retry — loop is dead, stop
152	          }
153	          continue;
154	        }
155	
156	        if (result.status === "unavailable") {
157	          // A backend/network failure, not a legitimate negative result.
158	          // Deliberately NOT counted in resolvedCount (see failedCount's
159	          // declaration) so an outage can never make the library look
160	          // "fully resolved" — LibraryLoadingBadge stays visible instead of
161	          // hiding on a false "done". Also deliberately NOT retried here
162	          // (that would spin the loop hot on a real outage); it simply
163	          // moves on, same as the rest of this loop's failure handling.
164	          updateArtist(artist.id, { status: "unavailable" });
165	          if (isLive()) setFailedCount((c) => c + 1);
166	          return;
167	        }
168	
169	        if (result.status === "resolved") {
170	          updateArtist(artist.id, {
171	            status: "resolved",
172	            lat: result.lat,
173	            lng: result.lng,
174	            placeName: result.placeName,
175	          });
176	        } else {
177	          updateArtist(artist.id, { status: "not_found" });
178	        }
179	        if (isLive()) setResolvedCount((c) => c + 1);
180	        return;
181	      }
182	    }
183	
184	    async function run() {
185	      setScopeMissing(false);
186	
187	      let followed;
188	      try {
189	        followed = await fetchFollowedArtists(token);
190	      } catch (err) {
191	        if (!isLive()) return;
192	        if (err.message === "SPOTIFY_ERROR:403") setScopeMissing(true);
193	        return;
194	      }
195	
196	      if (!isLive()) return;
197	
198	      const initial = followed.map((a) => ({ ...a, status: "pending" }));
199	      setArtists(initial);
200	      setTotal(initial.length);
201	      setResolvedCount(0);
202	      setFailedCount(0);
203	
204	      // One shared queue, N workers. `shift()` needs no lock: JavaScript is
205	      // single-threaded and there is no await between the shift and the
206	      // check, so two workers can never take the same artist.
207	      const queue = [...initial];
208	      await Promise.all(
209	        Array.from({ length: RESOLUTION_CONCURRENCY }, async () => {
210	          while (isLive()) {
211	            const artist = queue.shift();
212	            if (!artist) return;
213	            await resolveArtist(artist);
214	          }
215	        }),
216	      );
217	    }
218	
219	    run();
220	
221	    return () => {
222	      cancelled = true;
223	      controller.abort();
224	    };
225	  }, [token]);
226	
227	  return { artists, resolvedCount, total, scopeMissing, failedCount };
228	}
