18	export async function geocodeHandler(req, res, deps = {}) {
19	  if (req.method !== "POST") {
20	    return res.status(405).json({ error: "method_not_allowed" });
21	  }
22	
23	  // Actually validate the session rather than just checking the `rt`
24	  // cookie is present: openSession decrypts and verifies it (shape +
25	  // 30-day lifetime), throwing on anything forged/tampered/expired. Without
26	  // this, any party holding a garbage `rt=x` cookie could hit this endpoint
27	  // as an open, unauthenticated proxy in front of the shared, rate-limited
28	  // MusicBrainz/Nominatim lookups below. Only the "is this real" fact is
29	  // needed here — the decrypted refresh token itself is discarded.
30	  try {
31	    openSession(parseCookies(req.headers.cookie)[COOKIE_NAME]);
32	  } catch {
33	    return res.status(401).json({ error: "no_session" });
34	  }
35	
36	  const { artistId, artistName } = req.body ?? {};
37	  if (!artistId || !artistName) {
38	    return res.status(400).json({ error: "invalid_request" });
39	  }
40	
41	  // Resolved only once the request has cleared every guard above, so a
42	  // rejected request never pays for constructing a real Redis client.
43	  const redis = deps.redis ?? createRedisClient();
44	  const lookup = deps.lookupArtistLocation ?? lookupArtistLocation;
45	  const minIntervalMs = Number(process.env.GEOCODE_MIN_INTERVAL_MS ?? 1100);
46	
47	  // Every Redis call below (cache read, throttle locks, cache write) can
48	  // throw on an Upstash outage. Uncaught, that surfaces as a raw 500 —
49	  // indistinguishable, to the client, from any other failure — and
50	  // useLibraryArtists.js (reasonably) treats a non-200 as "this artist has
51	  // no location" (see its comment). Across an entire outage that marks
52	  // every artist not_found, so the loop finishes and the library reads as
53	  // "resolved successfully, and it's empty." Catching here and returning a
54	  // declared status keeps the failure in-vocabulary and lets the client
55	  // tell it apart from a legitimate negative result.
56	  const startedAt = Date.now();
57	  try {
58	    const cached = await getCachedArtist(redis, artistId);
59	    if (cached) {
60	      await recordLookupMetrics(redis, { counters: { cacheHits: 1 } });
61	      return res.status(200).json(cached);
62	    }
63	
64	    // Held for MUSICBRAINZ_CALLS_PER_LOOKUP intervals, not one: a lookup can
65	    // spend two MusicBrainz requests (artist search, then the area-parent
66	    // lookup that disambiguates "Aberdeen"), and they run back-to-back inside
67	    // lookup(). Reserving the airtime up front keeps the *average* rate inside
68	    // MusicBrainz's 1 req/s budget; trying to take a second slot mid-lookup
69	    // instead would just fail against the lock this one still holds, and the
70	    // client's retry would fail the same way forever. The tail of the
71	    // reservation is handed back below when the lookup turns out cheaper.
72	    const musicBrainzHoldMs = minIntervalMs * MUSICBRAINZ_CALLS_PER_LOOKUP;
73	    const lockToken = await acquireThrottle(
74	      redis,
75	      "musicbrainz",
76	      musicBrainzHoldMs,
77	    );
78	    const lockedAt = Date.now();
79	    if (!lockToken) {
80	      await recordLookupMetrics(redis, {
81	        counters: { throttledMusicBrainz: 1 },
82	      });
83	      // Retry when the lock actually frees, not after a fixed interval. A
84	      // constant here is wrong in both directions: too small burns a
85	      // round-trip on a lock that is still held, too large leaves it idle.
86	      return res.status(200).json({
87	        status: "throttled",
88	        retryAfterMs: await getThrottleRetryMs(
89	          redis,
90	          "musicbrainz",
91	          musicBrainzHoldMs,
92	        ),
93	      });
94	    }
95	
96	    // Whether the second MusicBrainz call actually happened is derivable
97	    // right here, without lookup() having to report it: it is spent exactly
98	    // when the area cache is consulted and misses. Wrapping the cache we
99	    // already pass in keeps shared/geocode.js free of both Redis and metrics.
100	    let areaCacheMissed = false;
101	    let areaCacheHit = false;
102	    const areaCache = {
103	      get: async (areaId) => {
104	        const parentName = await getCachedAreaParent(redis, areaId);
105	        if (parentName) areaCacheHit = true;
106	        else areaCacheMissed = true;
107	        return parentName;
108	      },
109	      set: (areaId, parentName) =>
110	        setCachedAreaParent(redis, areaId, parentName),
111	    };
112	
113	    // lookup() does both the MusicBrainz and (if needed) Nominatim calls
114	    // internally; a Nominatim-side throttle is acquired inside it.
115	    const upstreamStartedAt = Date.now();
116	    const location = await lookup(artistName, {
117	      acquireNominatimThrottle: async () =>
118	        Boolean(await acquireThrottle(redis, "nominatim", minIntervalMs)),
119	      areaCache,
120	    });
121	    const upstreamMs = Date.now() - upstreamStartedAt;
122	
123	    // Only one MusicBrainz call was actually spent unless the area cache
124	    // missed, so give back the second interval — but only the part that is
125	    // genuinely unowed: the one call we did make still owes a full interval
126	    // from when the lock was taken.
127	    const musicBrainzCalls = areaCacheMissed ? 2 : 1;
128	    if (musicBrainzCalls === 1) {
129	      await releaseThrottleAfter(
130	        redis,
131	        "musicbrainz",
132	        lockToken,
133	        minIntervalMs - (Date.now() - lockedAt),
134	      );
135	    }
136	
137	    const metricsFor = (outcome) => ({
138	      counters: {
139	        count: 1,
140	        totalMs: Date.now() - startedAt,
141	        totalUpstreamMs: upstreamMs,
142	        musicBrainzCalls,
143	        areaCacheHits: areaCacheHit ? 1 : 0,
144	        areaCacheMisses: areaCacheMissed ? 1 : 0,
145	        [outcome]: 1,
146	      },
147	      sample: {
148	        at: Date.now(),
149	        artist: artistName,
150	        ms: Date.now() - startedAt,
151	        upstreamMs,
152	        musicBrainzCalls,
153	        outcome,
154	      },
155	    });
156	
157	    if (location === "THROTTLED") {
158	      await recordLookupMetrics(redis, { counters: { throttledNominatim: 1 } });
159	      return res.status(200).json({
160	        status: "throttled",
161	        retryAfterMs: await getThrottleRetryMs(
162	          redis,
163	          "nominatim",
164	          minIntervalMs,
165	        ),
166	      });
167	    }
168	
169	    const value = location
170	      ? { status: "resolved", ...location, resolvedAt: Date.now() }
171	      : { status: "not_found", resolvedAt: Date.now() };
172	    await recordLookupMetrics(
173	      redis,
174	      metricsFor(location ? "resolved" : "notFound"),
175	    );
176	    await setCachedArtist(redis, artistId, value);
177	    return res.status(200).json(value);
178	  } catch (err) {
179	    console.error("geocodeHandler: Redis failure", err);
180	    return res.status(200).json({ status: "unavailable" });
181	  }
182	}
183	
184	export default function handler(req, res) {
185	  return geocodeHandler(req, res);
186	}
