6	// Same L.divIcon technique as AlbumBubble.jsx (64px circular image, white
7	// border, drop shadow) so a resolved library artist reads as the same kind
8	// of marker as the now-playing bubble, just without a popup — clicking it
9	// hands the artist off to onSelect instead.
10	export default function ArtistMarker({ artist, onSelect }) {
11	  const icon = useMemo(() => {
12	    const img = document.createElement("img");
13	    img.src = artist.imageUrl ?? "";
14	    img.alt = artist.name;
15	    img.style.cssText =
16	      "width:64px;height:64px;border-radius:50%;border:3px solid white;box-shadow:0 2px 12px rgba(0,0,0,0.5);display:block;";
17	    return L.divIcon({
18	      html: img,
19	      className: "",
20	      iconSize: [64, 64],
21	      iconAnchor: [32, 32],
22	      // Mirrors AlbumBubble.jsx's popupAnchor: [0, -36]. Leaflet's Tooltip
23	      // (like Popup) positions itself at iconAnchor + tooltipAnchor; with no
24	      // tooltipAnchor set it defaults to [0, 0] and the tooltip anchors at
25	      // the bubble's centre, overlapping it. -36 lifts it clear of the 64px
26	      // (32px-radius) circle by the same 4px margin the now-playing popup
27	      // uses, so both floating cards sit at the same height above their
28	      // bubble.
29	      tooltipAnchor: [0, -36],
30	    });
31	  }, [artist.imageUrl, artist.name]);
32	
33	  return (
34	    <Marker
35	      position={[artist.lat, artist.lng]}
36	      icon={icon}
37	      eventHandlers={{ click: () => onSelect?.(artist) }}
38	    >
39	      {/* Leaflet's Tooltip binds to the marker's mouseover/mouseout by
40	          default (no extra event wiring needed) — this is the hover-to-see
41	          behavior itself, not just its styling. */}
42	      <Tooltip className="artist-tooltip" direction="top" opacity={1}>
43	        <div className="artist-tooltip-name">{artist.name}</div>
44	        {/* Same 📍-prefixed treatment as AlbumPopupCard.jsx's place line,
45	            and same graceful omission when there's no place to show — never
46	            render a lone pin or the literal string "undefined". */}
47	        {artist.placeName && (
48	          <div className="artist-tooltip-place">📍 {artist.placeName}</div>
49	        )}
50	      </Tooltip>
51	    </Marker>
52	  );
53	}
